from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding="utf-8")
    if old not in text:
        raise SystemExit(f"expected source block not found in {path}")
    if text.count(old) != 1:
        raise SystemExit(f"source block is not unique in {path}: {text.count(old)}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")


mcp_server = ROOT / "minecraft_mod_ai" / "mcp_server.py"
replace_once(
    mcp_server,
    """@_stage_tool()\ndef search_project_rag(query: str, minecraft_version: str | None = None, limit: int = 6) -> dict[str, Any]:\n    \"\"\"Search the code-owned, version-pinned primary evidence catalog.\"\"\"\n    return _core().search_project_rag(query, minecraft_version, limit)\n""",
    """@_stage_tool()\ndef search_project_rag(query: str, limit: int = 6) -> dict[str, Any]:\n    \"\"\"Search evidence bound to the host-selected project target.\"\"\"\n    return _core().search_project_rag(query, None, limit)\n""",
)

